{
  "@context": "https://schema.org",
  "@type": "HowTo",
  "name": "응가메이트로 강아지 배변 기록 가족과 공유하는 법",
  "step": [
    { "@type": "HowToStep", "name": "앱 다운로드", "text": "iOS 또는 Android에서 응가메이트를 무료로 설치합니다." },
    { "@type": "HowToStep", "name": "강아지 프로필 만들고 가족 초대", "text": "강아지 프로필을 만들고 초대 링크로 가족을 추가합니다. 모두 같은 프로필을 함께 씁니다." },
    { "@type": "HowToStep", "name": "탭 한 번으로 기록", "text": "응가·쉬야·산책을 탭 한 번으로 기록합니다." },
    { "@type": "HowToStep", "name": "가족에게 실시간 알림", "text": "누가 기록하든 다른 가족의 앱에 바로 알림이 가고, 기록은 기록 탭에 날짜별로 쌓입니다." }
  ]
}

{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "가족이 여러 명이어도 하나의 기록으로 공유되나요?",
      "acceptedAnswer": { "@type": "Answer", "text": "네. 강아지 한 마리당 프로필 하나를 가족 구성원 전체가 함께 씁니다. 누가 기록해도 같은 이력에 쌓이고 모두에게 알림이 갑니다." }
    },
    {
      "@type": "Question",
      "name": "강아지를 여러 마리 키우면 각각 따로 공유할 수 있나요?",
      "acceptedAnswer": { "@type": "Answer", "text": "네. 다견가정도 강아지마다 프로필을 나눠서 각각 가족과 공유할 수 있습니다." }
    },
    {
      "@type": "Question",
      "name": "무료인가요?",
      "acceptedAnswer": { "@type": "Answer", "text": "네, 응가메이트는 무료 앱입니다." }
    }
  ]
}
